// All visible text of the panel, in Korean (default) and English. Both dictionaries use the same keys;
// a key that is missing in English silently falls back to Korean. A text with changing parts is ONE
// template string ("{days}"), never several pieces glued together, so every text is a single node.

export type Locale = "ko" | "en";
export const LOCALES: readonly Locale[] = ["ko", "en"];
export const DEFAULT_LOCALE: Locale = "ko";
export const LOCALE_STORAGE_KEY = "admin_locale";

export const isLocale = (v: unknown): v is Locale => v === "ko" || v === "en";

